package com.yeeyuan;
import java.util.*;
import java.sql.Timestamp;
import java.time.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.yeeyuan.Db.*;
@Service
public class Admin {
 final Db db;final Auth auth;final Crypto crypto;final Settings config;final Orders orders;
 public Admin(Db db,Auth auth,Crypto crypto,Settings config,Orders orders){this.db=db;this.auth=auth;this.crypto=crypto;this.config=config;this.orders=orders;}
 public Object tables(){return Map.of("items",db.jdbc.queryForList("SELECT t.id,t.code,v.id AS visit_id,v.expires_at FROM dining_table t LEFT JOIN table_visit v ON v.table_id=t.id AND v.status='OPEN' AND v.expires_at>now() ORDER BY t.code"));}
 @Transactional public Object rotate(Auth.User u,UUID id){String token=Crypto.token();db.jdbc.update("UPDATE dining_table SET qr_token_hash=? WHERE id=?",Crypto.hash(token),id);db.audit(u.id(),"ROTATE_TABLE_QR",id);return Map.of("tableId",id,"url",config.publicAppUrl()+"/?tableToken="+token);}
 @Transactional public Object open(Auth.User u,UUID table){db.one("SELECT id FROM dining_table WHERE id=? AND active=true FOR UPDATE",table);db.jdbc.update("UPDATE table_visit SET status='EXPIRED',closed_at=now() WHERE table_id=? AND status='OPEN' AND expires_at<now()",table);if(!db.jdbc.queryForList("SELECT id FROM table_visit WHERE table_id=? AND status='OPEN'",table).isEmpty())throw new Problem(409,"VISIT_OPEN","โต๊ะนี้มีรอบเปิดอยู่แล้ว");String pin=Crypto.pin();UUID id=UUID.randomUUID();Instant expires=Instant.now().plusSeconds(5400);db.jdbc.update("INSERT INTO table_visit(id,table_id,join_pin_hash,status,expires_at,opened_by) VALUES(?,?,?,'OPEN',?,?)",id,table,auth.encodePassword(pin),Timestamp.from(expires),u.id());db.audit(u.id(),"OPEN_TABLE",id);return Map.of("id",id,"pin",pin,"expiresAt",expires.toString());}
 @Transactional public Object join(Auth.User u,String token,String pin){var v=db.one("SELECT v.*,t.code FROM table_visit v JOIN dining_table t ON t.id=v.table_id WHERE t.qr_token_hash=? AND t.active=true AND v.status='OPEN' AND v.expires_at>now() FOR SHARE OF v",Crypto.hash(token));if(!auth.matchesPassword(pin,str(v,"join_pin_hash")))throw new Problem(403,"INVALID_PIN","รหัสโต๊ะไม่ถูกต้อง");db.jdbc.update("INSERT INTO table_visit_member(visit_id,user_id) VALUES(?,?) ON CONFLICT DO NOTHING",uuid(v,"id"),u.id());return Map.of("id",v.get("id"),"tableCode",v.get("code"),"expiresAt",time(v,"expires_at").toString());}
 @Transactional public void close(Auth.User u,UUID id){db.jdbc.update("UPDATE table_visit SET status='CLOSED',closed_at=now(),version=version+1 WHERE id=? AND status='OPEN'",id);db.audit(u.id(),"CLOSE_TABLE",id);}
 @Transactional public void availability(Auth.User u,boolean value){db.jdbc.update("UPDATE store SET accepting_orders=?",value);db.audit(u.id(),"STORE_AVAILABILITY",null);}
 public Object stock(UUID id){var s=db.one("SELECT * FROM inventory_stock WHERE product_id=?",id);var result=new LinkedHashMap<String,Object>();result.put("productId",id);result.put("availableQty",s.get("available_qty"));result.put("version",s.get("version"));return result;}
 @Transactional public Object stock(Auth.User u,UUID id,Map<String,Object> b){var s=db.one("SELECT * FROM inventory_stock WHERE product_id=? FOR UPDATE",id);if(num(s,"version")!=((Number)b.get("version")).longValue())throw new Problem(409,"STALE_VERSION","จำนวนขายเปลี่ยนแล้ว");Object value=b.get("availableQty");if(value!=null&&((Number)value).intValue()<0)throw Problem.bad("จำนวนต้องไม่ติดลบ");db.jdbc.update("UPDATE inventory_stock SET available_qty=?,version=version+1,updated_at=now() WHERE product_id=?",value,id);db.audit(u.id(),"STOCK_UPDATE",id);return stock(id);}
 @Transactional public void product(Auth.User u,UUID id,Map<String,Object> b){db.one("SELECT id FROM store LIMIT 1 FOR UPDATE");var p=db.one("SELECT * FROM product WHERE id=? FOR UPDATE",id);if(num(p,"version")!=((Number)b.get("version")).longValue())throw new Problem(409,"STALE_VERSION","เมนูเปลี่ยนแล้ว");long price=((Number)b.get("priceSatang")).longValue();String name=str(b,"name");if(price<0||price>500000||name.isBlank()||name.length()>100)throw Problem.bad("ชื่อหรือราคาไม่ถูกต้อง");db.jdbc.update("UPDATE product SET name=?,price_satang=?,active=?,sold_out=?,version=version+1 WHERE id=?",name,price,Boolean.TRUE.equals(b.get("active")),Boolean.TRUE.equals(b.get("soldOut")),id);db.jdbc.update("UPDATE store SET catalog_version=catalog_version+1");db.audit(u.id(),"MENU_UPDATE",id);}
 public Object report(LocalDate date){Instant from=date.atStartOfDay(ZoneId.of("Asia/Bangkok")).toInstant(),to=date.plusDays(1).atStartOfDay(ZoneId.of("Asia/Bangkok")).toInstant();var p=db.one("SELECT COALESCE(sum(COALESCE(actual_amount_satang,amount_satang)),0) AS received,COALESCE(sum(fee_satang),0) AS fee,COALESCE(sum(fee_vat_satang),0) AS vat FROM payment_attempt WHERE status='SUCCEEDED' AND paid_at>=? AND paid_at<?",Timestamp.from(from),Timestamp.from(to));var r=db.one("SELECT COALESCE(sum(amount_satang),0) AS refunded FROM refund_case WHERE status='PAID' AND paid_at>=? AND paid_at<?",Timestamp.from(from),Timestamp.from(to));return Map.of("date",date.toString(),"timezone","Asia/Bangkok","receivedSatang",p.get("received"),"gatewayFeeSatang",p.get("fee"),"gatewayFeeVatSatang",p.get("vat"),"refundedSatang",r.get("refunded"),"note","ยอดโอนธนาคารต้องกระทบกับ Gateway และ statement แยก");}
 @Transactional public Object refund(Auth.User u,Map<String,Object> b,UUID key){var previous=orders.cached(u,"/staff/refunds",key,b);if(previous!=null)return previous;UUID aid=UUID.fromString(str(b,"attemptId"));var a=db.one("SELECT * FROM payment_attempt WHERE id=? AND status='SUCCEEDED' FOR UPDATE",aid);long amount=((Number)b.get("amountSatang")).longValue();if(amount<=0||amount>(a.get("actual_amount_satang")==null?num(a,"amount_satang"):num(a,"actual_amount_satang"))||str(b,"reason").isBlank())throw Problem.bad("ยอดหรือเหตุผลคืนเงินไม่ถูกต้อง");UUID id=UUID.randomUUID();db.jdbc.update("INSERT INTO refund_case(id,attempt_id,amount_satang,reason,requested_by) VALUES(?,?,?,?,?)",id,aid,amount,str(b,"reason"),u.id());var result=Map.<String,Object>of("id",id,"status","REQUESTED","version",0);orders.cache(u,"/staff/refunds",key,b,result);db.audit(u.id(),"REFUND_REQUEST",id);return result;}
 @Transactional public Object approve(Auth.User u,UUID id,long version){var first=db.one("SELECT * FROM refund_case WHERE id=?",id);var a=db.one("SELECT * FROM payment_attempt WHERE id=? FOR UPDATE",uuid(first,"attempt_id"));var r=db.one("SELECT * FROM refund_case WHERE id=? FOR UPDATE",id);if(num(r,"version")!=version||!str(r,"status").equals("REQUESTED"))throw new Problem(409,"STALE_VERSION","รายการคืนเงินเปลี่ยนแล้ว");if(uuid(r,"requested_by").equals(u.id())&&!u.roles().contains("OWNER"))throw new Problem(403,"SECOND_APPROVER_REQUIRED","ต้องให้คนละคนอนุมัติ");long used=db.jdbc.queryForObject("SELECT COALESCE(sum(amount_satang),0) FROM refund_case WHERE attempt_id=? AND status IN ('APPROVED','PAID')",Long.class,uuid(a,"id"));long paid=a.get("actual_amount_satang")==null?num(a,"amount_satang"):num(a,"actual_amount_satang");if(used+num(r,"amount_satang")>paid)throw Problem.bad("ยอดคืนรวมเกินเงินที่รับจริง");db.jdbc.update("UPDATE refund_case SET status='APPROVED',approved_by=?,approved_at=now(),version=version+1 WHERE id=?",u.id(),id);db.audit(u.id(),"REFUND_APPROVE",id);return Map.of("id",id,"status","APPROVED","version",version+1);}
 @Transactional public Object refundPaid(Auth.User u,UUID id,Map<String,Object> b){var preliminary=db.one("SELECT r.attempt_id,p.order_id FROM refund_case r JOIN payment_attempt p ON p.id=r.attempt_id WHERE r.id=?",id);UUID oid=uuid(preliminary,"order_id"),aid=uuid(preliminary,"attempt_id");db.one("SELECT id FROM orders WHERE id=? FOR UPDATE",oid);db.one("SELECT id FROM payment_attempt WHERE id=? FOR UPDATE",aid);var r=db.one("SELECT * FROM refund_case WHERE id=? FOR UPDATE",id);if(num(r,"version")!=((Number)b.get("version")).longValue()||!str(r,"status").equals("APPROVED"))throw new Problem(409,"STALE_VERSION","รายการคืนเงินไม่พร้อม");if(str(b,"bankReference").isBlank()||str(b,"evidenceRef").isBlank())throw Problem.bad("ต้องบันทึกหลักฐานโอนคืน");db.jdbc.update("UPDATE refund_case SET status='PAID',paid_by=?,paid_at=now(),bank_reference=?,evidence_ref=?,version=version+1 WHERE id=?",u.id(),str(b,"bankReference"),str(b,"evidenceRef"),id);long received=db.jdbc.queryForObject("SELECT COALESCE(sum(COALESCE(actual_amount_satang,amount_satang)),0) FROM payment_attempt WHERE order_id=? AND status='SUCCEEDED'",Long.class,oid);long refunded=db.jdbc.queryForObject("SELECT COALESCE(sum(r.amount_satang),0) FROM refund_case r JOIN payment_attempt p ON p.id=r.attempt_id WHERE p.order_id=? AND r.status='PAID'",Long.class,oid);db.jdbc.update("UPDATE orders SET payment_status=?,version=version+1 WHERE id=?",refunded>=received?"REFUNDED":"PARTIALLY_REFUNDED",oid);db.audit(u.id(),"REFUND_CONFIRMED",id);return Map.of("id",id,"status","PAID");}
 @Transactional public Object cancel(Auth.User u,UUID id,boolean manager,String reason){var o=manager?db.one("SELECT * FROM orders WHERE id=? FOR UPDATE",id):db.one("SELECT * FROM orders WHERE id=? AND customer_id=? FOR UPDATE",id,u.id());if(!manager&&!str(o,"status").equals("AWAITING_PAYMENT"))throw new Problem(409,"CONTACT_STORE","ชำระแล้วกรุณาติดต่อร้านเพื่อขอยกเลิก");if(db.jdbc.queryForObject("SELECT count(*) FROM payment_attempt WHERE order_id=? AND status IN ('CREATING','UNKNOWN','PENDING')",Integer.class,id)>0)throw new Problem(409,"PAYMENT_UNRESOLVED","ยังมีการจ่ายที่ไม่ทราบผล กรุณารอหมดอายุและตรวจยอดก่อนยกเลิก");if(Set.of("COMPLETED","CANCELLED","EXPIRED").contains(str(o,"status")))throw new Problem(409,"INVALID_STATE","ยกเลิกออเดอร์นี้ไม่ได้");orders.release(id);db.jdbc.update("UPDATE orders SET status='CANCELLED',version=version+1 WHERE id=?",id);db.jdbc.update("UPDATE kitchen_ticket SET status='CANCELLED',version=version+1 WHERE order_id=?",id);db.event(id,str(o,"status"),"CANCELLED",u.id(),reason);db.audit(u.id(),"ORDER_CANCEL",id);return Map.of("id",id,"status","CANCELLED","refundRequired",str(o,"payment_status").equals("PAID"));}
}
